style.css:
@-moz-document domain("twitter.com"), domain("x.com") {
:root {
    --pink-bg: #fff0f5;
    --pink-bg-soft: #ffe4ef;
    --pink-card: #ffffff;
    --pink-primary: #ff6fa5;
    --pink-primary-hover: #ff4f91;
    --pink-accent: #ffb6d9;
    --pink-border: #ffc9e0;
    --pink-text: #ffafcc;
    --pink-text-soft: #8a5c73;
    --pink-like: #ff5c8a;
  }

  /* Base background */
  body,
  [data-testid="primaryColumn"],
  [data-testid="sidebarColumn"] {
    background-color: var(--pink-bg) !important;
    color: var(--pink-text) !important;
  }

  /* Header / nav bar */
  header,
  [data-testid="AppTabBar_Home_Link"],
  nav {
    background-color: var(--pink-bg-soft) !important;
    border-bottom: 2px solid var(--pink-border) !important;
  }

  /* Tweets / cards */
  article {
    background-color: var(--pink-card) !important;
    border: 1px solid var(--pink-border) !important;
    border-radius: 18px !important;
    margin: 8px 0 !important;
    box-shadow: 0 2px 8px rgba(255, 111, 165, 0.12);
    transition: transform 0.15s ease;
  }

  article:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 14px rgba(255, 111, 165, 0.2);
  }

  /* Text */
  article span,
  article div {
    color: var(--pink-text) !important;
  }

  /* Links / usernames */
  a[role="link"] {
    color: var(--pink-primary) !important;
  }

  /* Primary action buttons (Tweet / Post button, incl. floating compose button) */
  [data-testid="tweetButtonInline"],
  [data-testid="tweetButton"],
  [data-testid="SideNav_NewTweet_Button"],
  a[href="/compose/post"],
  a[href="/compose/tweet"] {
    background-color: #f8ad9d !important;
    border-radius: 999px !important;
    position: relative !important;
  }

  /* Hide the original "Post" label (keeps layout, doesn't fight nested spans) */
  [data-testid="tweetButtonInline"] span,
  [data-testid="tweetButton"] span,
  [data-testid="SideNav_NewTweet_Button"] span,
  a[href="/compose/post"] span,
  a[href="/compose/tweet"] span {
    visibility: hidden !important;
  }

  /* Cute emoticon centered over the button */
  [data-testid="tweetButtonInline"]::after,
  [data-testid="tweetButton"]::after,
  [data-testid="SideNav_NewTweet_Button"]::after,
  a[href="/compose/post"]::after,
  a[href="/compose/tweet"]::after {
    content: "(⁄ ⁄•⁄ω⁄•⁄ ⁄)";
    visibility: visible !important;
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    color: #fff !important;
    font-size: 15px;
    font-weight: 700;
    white-space: nowrap;
  }

  [data-testid="tweetButtonInline"]:hover,
  [data-testid="tweetButton"]:hover,
  [data-testid="SideNav_NewTweet_Button"]:hover,
  a[href="/compose/post"]:hover,
  a[href="/compose/tweet"]:hover {
    background-color: #f6987f !important;
  }

  /* ============================================
     ? Cutecore emoticon icons
     Hides the default SVG icons and swaps in
     kaomoji-style text emoticons instead
     ============================================ */

  /* Like button heart -> (♡ᵕ♡) */
  [data-testid="like"] svg,
  [data-testid="unlike"] svg {
    display: none !important;
  }
  [data-testid="like"]::before {
    content: "(♡ᵕ♡)";
  }
  [data-testid="unlike"]::before {
    content: "(´♡‿♡`)";
    color: var(--pink-like) !important;
  }

  /* Retweet icon -> (◕ᴗ◕) */
  [data-testid="retweet"] svg,
  [data-testid="unretweet"] svg {
    display: none !important;
  }
  [data-testid="retweet"]::before {
    content: "(◕ᴗ◕)";
  }
  [data-testid="unretweet"]::before {
    content: "(◕ᴗ◕)";
    color: var(--pink-primary) !important;
  }

  /* Reply icon -> (˶ᵔ ᵕ ᵔ˶) */
  [data-testid="reply"] svg {
    display: none !important;
  }
  [data-testid="reply"]::before {
    content: "(˶ᵔ ᵕ ᵔ˶)";
  }

  /* Share icon -> (｡•ᴗ•｡) */
  [aria-label="Share post"] svg {
    display: none !important;
  }
  [aria-label="Share post"]::before {
    content: "(｡•ᴗ•｡)";
  }

  /* Bookmark icon -> (￣ω￣) */
  [data-testid="bookmark"] svg,
  [data-testid="removeBookmark"] svg {
    display: none !important;
  }
  [data-testid="bookmark"]::before,
  [data-testid="removeBookmark"]::before {
    content: "(￣ω￣)";
  }

  /* Make sure emoticon icons sit inline in place of the old icon,
     never stacked above any label/count text */
  [data-testid="like"],
  [data-testid="unlike"],
  [data-testid="retweet"],
  [data-testid="unretweet"],
  [data-testid="reply"],
  [aria-label="Share post"],
  [data-testid="bookmark"],
  [data-testid="removeBookmark"] {
    display: inline-flex !important;
    flex-direction: row !important;
    align-items: center;
    justify-content: center;
    line-height: 1;
    font-family: "Comic Sans MS", "Segoe UI", sans-serif !important;
    font-size: 13px !important;
    font-weight: 700 !important;
    letter-spacing: -0.5px;
    color: var(--pink-text-soft) !important;
  }

  /* Profile picture ring */
  img[src*="profile_images"] {
    border: 2px solid var(--pink-accent) !important;
    border-radius: 50% !important;
  }

  /* Search bar */
  [data-testid="SearchBox_Search_Input"] {
    background-color: var(--pink-bg-soft) !important;
    border: 1px solid var(--pink-border) !important;
    border-radius: 999px !important;
    color: var(--pink-text) !important;
  }

  /* Trending / "What's happening" panel */
  [data-testid="trend"] {
    background-color: var(--pink-card) !important;
    border-radius: 12px !important;
    margin-bottom: 6px !important;
  }

  /* Follow buttons -> (๑>ᴗ<๑) */
  [data-testid$="-follow"] {
    background-color: var(--pink-primary) !important;
    color: #fff !important;
    border-radius: 999px !important;
    font-size: 0 !important; /* hide the original "Follow" text */
  }
  [data-testid$="-follow"]::after {
    content: "(๑>ᴗ<๑)";
    font-size: 14px;
    color: #fff !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-track {
    background: var(--pink-bg);
  }
  ::-webkit-scrollbar-thumb {
    background: var(--pink-accent);
    border-radius: 10px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: var(--pink-primary);
  }

  /* ============================================
     ? Cutecore nav icons (left sidebar)
     ============================================ */

  [data-testid="AppTabBar_Home_Link"] svg {
    display: none !important;
  }
  [data-testid="AppTabBar_Home_Link"]::before {
    content: "(⌒ᴗ⌒)";
    margin-right: 6px;
  }

  [data-testid="AppTabBar_Explore_Link"] svg,
  [data-testid="AppTabBar_Search_Link"] svg {
    display: none !important;
  }
  [data-testid="AppTabBar_Explore_Link"]::before,
  [data-testid="AppTabBar_Search_Link"]::before {
    content: "(˶˃ ᵕ ˂˶)";
    margin-right: 6px;
  }

  [data-testid="AppTabBar_Notifications_Link"] svg {
    display: none !important;
  }
  [data-testid="AppTabBar_Notifications_Link"]::before {
    content: "(๑˃ᴗ˂)ﻭ";
    margin-right: 6px;
  }

  [data-testid="AppTabBar_DirectMessage_Link"] svg {
    display: none !important;
  }
  [data-testid="AppTabBar_DirectMessage_Link"]::before {
    content: "(´｡• ᵕ •｡`)";
    margin-right: 6px;
  }

  /* X logo (top of sidebar) -> cute My Melody icon
     embedded directly as base64 so it doesn't depend
     on any external image host.
     Exact element confirmed via DevTools inspection:
     <a href="/home" aria-label="X" role="link"> */
  a[href="/home"][aria-label="X"] svg {
    display: none !important;
  }
  a[href="/home"][aria-label="X"]::before {
    content: "";
    display: inline-block;
    width: 60px;
    height: 60px;
    background-image: url('data:image/png;base64,');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
  }

  /* Grok tab */
  a[href="/i/grok"] svg,
  [data-testid="AppTabBar_Grok"] svg {
    display: none !important;
  }
  a[href="/i/grok"]::before,
  [data-testid="AppTabBar_Grok"]::before {
    content: "(·ᴗ·)";
    margin-right: 6px;
  }

  /* Profile tab */
  [data-testid="AppTabBar_Profile_Link"] svg {
    display: none !important;
  }
  [data-testid="AppTabBar_Profile_Link"]::before {
    content: "(◕ω◕)";
    margin-right: 6px;
  }

  /* More menu */
  [data-testid="AppTabBar_More_Menu"] svg,
  [aria-label="More menu items"] svg {
    display: none !important;
  }
  [data-testid="AppTabBar_More_Menu"]::before,
  [aria-label="More menu items"]::before {
    content: "(・∀・)";
    margin-right: 6px;
  }

  /* History (e.g. Grok chat history sidebar item) */
  [aria-label="History"] svg,
  [data-testid="Grok_history"] svg {
    display: none !important;
  }
  [aria-label="History"]::before,
  [data-testid="Grok_history"]::before {
    content: "(｡◕‿◕｡)";
    margin-right: 6px;
  }

  [data-testid="AppTabBar_Home_Link"],
  [data-testid="AppTabBar_Explore_Link"],
  [data-testid="AppTabBar_Search_Link"],
  [data-testid="AppTabBar_Notifications_Link"],
  [data-testid="AppTabBar_DirectMessage_Link"],
  a[href="/i/grok"],
  [data-testid="AppTabBar_Grok"],
  [data-testid="AppTabBar_Profile_Link"],
  [data-testid="AppTabBar_More_Menu"],
  [aria-label="More menu items"],
  [aria-label="History"],
  [data-testid="Grok_history"] {
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    font-family: "Comic Sans MS", "Segoe UI", sans-serif !important;
    font-size: 15px !important;
    font-weight: 700 !important;
    color: var(--pink-primary) !important;
  }

  /* Force the label text itself (not just the parent link) to match -
     Twitter's own CSS sets an explicit color on the inner span/text,
     which otherwise overrides the color set above */
  [data-testid="AppTabBar_Home_Link"] *,
  [data-testid="AppTabBar_Explore_Link"] *,
  [data-testid="AppTabBar_Search_Link"] *,
  [data-testid="AppTabBar_Notifications_Link"] *,
  [data-testid="AppTabBar_DirectMessage_Link"] *,
  a[href="/i/grok"] *,
  [data-testid="AppTabBar_Grok"] *,
  [data-testid="AppTabBar_Profile_Link"] *,
  [data-testid="AppTabBar_More_Menu"] *,
  [aria-label="More menu items"] *,
  [aria-label="History"] *,
  [data-testid="Grok_history"] *,
  [data-testid$="-follow"] * {
    color: var(--pink-primary) !important;
  }

  /* Broad fallback: force every bit of text inside the entire left
     sidebar nav to match, regardless of exact testid naming - this
     is what actually guarantees the labels turn pink */
  nav,
  nav *,
  [aria-label="Primary"],
  [aria-label="Primary"] * {
    color: var(--pink-primary) !important;
  }

  /* ============================================
     ? Bubble hover animation
     A little squish-and-pop bounce plus an
     expanding ripple, like a soft bubble
     ============================================ */

  @keyframes bubblePop {
    0%   { transform: scale(1); }
    40%  { transform: scale(1.18); }
    65%  { transform: scale(0.94); }
    100% { transform: scale(1.06); }
  }

  @keyframes bubbleRipple {
    0%   { box-shadow: 0 0 0 0 rgba(255, 175, 204, 0.65); }
    100% { box-shadow: 0 0 0 14px rgba(255, 175, 204, 0); }
  }

  /* Post button + Follow buttons + action icons + nav tabs */
  [data-testid="tweetButtonInline"],
  [data-testid="tweetButton"],
  [data-testid="SideNav_NewTweet_Button"],
  a[href="/compose/post"],
  a[href="/compose/tweet"],
  [data-testid$="-follow"],
  [data-testid="like"],
  [data-testid="unlike"],
  [data-testid="retweet"],
  [data-testid="unretweet"],
  [data-testid="reply"],
  [aria-label="Share post"],
  [data-testid="bookmark"],
  [data-testid="removeBookmark"],
  [data-testid="AppTabBar_Home_Link"],
  [data-testid="AppTabBar_Explore_Link"],
  [data-testid="AppTabBar_Search_Link"],
  [data-testid="AppTabBar_Notifications_Link"],
  [data-testid="AppTabBar_DirectMessage_Link"],
  a[href="/i/grok"],
  [data-testid="AppTabBar_Grok"],
  [data-testid="AppTabBar_Profile_Link"],
  [data-testid="AppTabBar_More_Menu"],
  [aria-label="More menu items"],
  [aria-label="History"],
  [data-testid="Grok_history"] {
    transition: transform 0.15s ease-out !important;
    border-radius: 999px !important;
  }

  [data-testid="tweetButtonInline"]:hover,
  [data-testid="tweetButton"]:hover,
  [data-testid="SideNav_NewTweet_Button"]:hover,
  a[href="/compose/post"]:hover,
  a[href="/compose/tweet"]:hover,
  [data-testid$="-follow"]:hover,
  [data-testid="like"]:hover,
  [data-testid="unlike"]:hover,
  [data-testid="retweet"]:hover,
  [data-testid="unretweet"]:hover,
  [data-testid="reply"]:hover,
  [aria-label="Share post"]:hover,
  [data-testid="bookmark"]:hover,
  [data-testid="removeBookmark"]:hover,
  [data-testid="AppTabBar_Home_Link"]:hover,
  [data-testid="AppTabBar_Explore_Link"]:hover,
  [data-testid="AppTabBar_Search_Link"]:hover,
  [data-testid="AppTabBar_Notifications_Link"]:hover,
  [data-testid="AppTabBar_DirectMessage_Link"]:hover,
  a[href="/i/grok"]:hover,
  [data-testid="AppTabBar_Grok"]:hover,
  [data-testid="AppTabBar_Profile_Link"]:hover,
  [data-testid="AppTabBar_More_Menu"]:hover,
  [aria-label="More menu items"]:hover,
  [aria-label="History"]:hover,
  [data-testid="Grok_history"]:hover {
    animation: bubblePop 0.45s ease-out, bubbleRipple 0.55s ease-out !important;
  }
}
